window.products.push({"id":644309,"name":"Ancient Greek Bronze Museum Statue Replica of Snake Goddess (251)","category":"homeandappliances","retail price":22.7,"sale price":null,"image":"https://m.media-amazon.com/images/I/41Asb6eetsL._AC_.jpg","description":"Ancient Greek Snake Goddess Code: 251 Dimensions: 8x6 cm 3.16x2.37 in Weight: 100gr Material: BRONZE Color: GREEN/GOLD OXIDIGATION This is a handmade statue of Snake Goddess made in Greece, from 100% bronze using the traditional “lost wax” technique. This is the same technique used by the ancient Greeks to create bronze sculptures and arsenal. The prototype which it was made by is a museum exhibit. The Green/Gold color is given through the process of oxidization","images":["https://m.media-amazon.com/images/I/41Asb6eetsL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Iconsgr","source_asin":"B00GFSVSKW","category_path":"Home & Kitchen"},"sku":"BM-644309","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00GFSVSKW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00GFSVSKW","price_pending":true,"merchant_ready":false});
